_choice_git_args() {
    local store_dir
    store_dir="$(_helper_pass_store_dir)"
    [[ -n "$store_dir" ]] || return 0
    (cd "$store_dir" && _argc_util_comp_subcommand 0 git)
}

_choice_gpg_id() {
    command -v gpg >/dev/null 2>&1 || return 0
    gpg --list-keys --with-colons 2>/dev/null | gawk -F: '$1 == "uid" { print $10 }'
}

_choice_pass_dir() {
    local store_dir
    store_dir="$(_helper_pass_store_dir)"
    [[ -n "$store_dir" ]] || return 0
    command find "$store_dir" -type f -name '*.gpg' 2>/dev/null |
        gawk -v prefix="$store_dir" '
            index($0, prefix) == 1 {
                n = split(substr($0, length(prefix) + 1), parts, "/")
                dir = ""
                for (i = 1; i < n; i++) {
                    dir = dir parts[i] "/"
                    print dir
                }
            }' |
        _argc_util_comp_parts / |
        sed '/^$/d'
}

_choice_pass_name() {
    local store_dir
    store_dir="$(_helper_pass_store_dir)"
    [[ -n "$store_dir" ]] || return 0
    command find "$store_dir" -type f -name '*.gpg' 2>/dev/null |
        gawk -v prefix="$store_dir" '
            index($0, prefix) == 1 {
                name = substr($0, length(prefix) + 1)
                sub(/\.gpg$/, "", name)
                print name
            }' |
        _argc_util_comp_parts /
}

_helper_pass_store_dir() {
    local store_dir="${PASSWORD_STORE_DIR:-$HOME/.password-store}"
    [[ -d "$store_dir" ]] || return 0
    printf '%s/\n' "${store_dir%/}"
}
